export function getArticleBySlug(slug) {
  return blogArticles.find(a => a.slug === slug) || null;
}

export function getRecentArticles(count = 10) {
  return [...blogArticles]
    .sort((a, b) => new Date(b.publishedDate) - new Date(a.publishedDate))
    .slice(0, count);
}

export function getArticlesByTag(tag) {
  return blogArticles.filter(a => a.tags.includes(tag));
}
